head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onblankclick]<br/>Header, Body, SubTotal, Footer 가 아닌 GridView 컴포넌트의 빈 영역을 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "PointerEvent 객체가 전달됩니다.",
        "빈 영역이란 Header, Body, SubTotal, Footer 등 GridView 컴포넌트가 렌더링한 영역이 아닌 영역을 의미합니다.",
        "데이터가 로드되기 전의 공간 또는 로드된 데이터가 표시되고 하단에 남는 공간을 클릭하는 경우 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 적은 데이터(2행)만 로드 → 그리드 하단에 빈 영역이 남도록 구성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 2);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="데이터 2행만 로드 + 그리드 높이를 크게 설정. 데이터 하단의 빈 영역을 마우스 왼쪽 버튼으로 클릭하여 onblankclick 발생 확인"', '', 'label1');

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    let eList = $c.gcm.createEList(["onblankclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody, 높이를 크게 잡아 데이터 하단 빈 영역 확보)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:520px;height:380px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onblankclick 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="컬럼1"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="컬럼2"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="컬럼3"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="컬럼4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" dataType="text" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" dataType="text" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" dataType="text" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" dataType="text" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onblankclick : GridView 의 빈 영역(데이터 하단 등)을 마우스 왼쪽 버튼으로 클릭할 때 발생
//  - e : PointerEvent 객체 → 개별 속성 나열 없이 e 객체 자체만 한 줄 출력
scwin.target1_onblankclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblankclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
